// Package sys provides platform-specific low-level system call
// abstractions for Linux, macOS, and Windows.
//
// Each platform implements getDefaultInfo using the appropriate
// system APIs (e.g., uname on Unix, Win32 on Windows).
//
// For system calls not available in the standard library,
// consider using golang.org/x/sys/unix (Unix) or
// golang.org/x/sys/windows (Windows).
package sys

// SystemInfo holds system information gathered from low-level
// platform-specific system calls.
type SystemInfo struct {
	// Platform is the runtime.GOOS value.
	Platform string
	// OS is the OS version string (e.g., kernel release from uname).
	OS string
	// Arch is the runtime.GOARCH value.
	Arch string
}

// GetInfo returns system information using platform-specific
// low-level system calls.
func GetInfo() (*SystemInfo, error) {
	return getDefaultInfo()
}

// getDefaultInfo is implemented in platform-specific files
// (linux.go, darwin.go, windows.go) using build tags.
func getDefaultInfo() (*SystemInfo, error) {
	return nil, fmt.Errorf("not implemented on this platform")
}

//go:build linux

package sys

import (
	"fmt"
	"runtime"
	"syscall"
)

func getDefaultInfo() (*SystemInfo, error) {
	var buf syscall.Utsname
	if err := syscall.Uname(&buf); err != nil {
		return nil, fmt.Errorf("uname: %w", err)
	}
	return &SystemInfo{
		Platform: runtime.GOOS,
		OS:       fmt.Sprintf("%s %s", trimNull(buf.Release[:]), trimNull(buf.Machine[:])),
		Arch:     runtime.GOARCH,
	}, nil
}

func trimNull(b []byte) string {
	for i, c := range b {
		if c == 0 {
			return string(b[:i])
		}
	}
	return string(b)
}

